<div class="content-wrapper"><section class="content"><div class="et-card">
  <div class="et-card-header"><div><h3>สถานะครุภัณฑ์</h3><small class="et-card-subtitle">สถานะหลัก 3 รายการถูกล็อกเพื่อรักษาการทำงานของระบบ</small></div><a class="btn btn-success" href="<?php echo site_url('staff/add_status'); ?>"><i class="fa fa-plus-circle"></i> เพิ่มสถานะ</a></div>
  <div class="table-responsive"><table class="table et-table dataTable"><thead><tr><th>#</th><th>ชื่อสถานะ</th><th>ประเภท</th><th>จัดการ</th></tr></thead><tbody>
  <?php if(empty($querystatus)): ?><tr><td colspan="4" class="et-empty">ยังไม่มีสถานะ</td></tr><?php else: foreach($querystatus as $rs): $locked=in_array((int)$rs->s_id,array(1,2,3),TRUE); ?>
